import org.junit.jupiter.api.Test;
import static org.mockito.Mockito.*;

public class OnlineStockSpanTest {

    private OnlineStockSpan onlineStockSpan = new OnlineStockSpan();

    @Test
    public void test_next_no_price() {
        when(onlineStockSpan.next(anyInt())).thenReturn(-1);
        int price = 5;
        int result = onlineStockSpan.next(price);
        assertEquals(-1, result);
    }

    @Test
    public void test_next_one_price() {
        List<Integer> prices = new ArrayList<>();
        prices.add(4);
        prices.add(3);
        prices.add(2);
        prices.add(0);
        prices.add(3);
        when(onlineStockSpan.next(anyInt())).thenReturn(-1);
        int result = onlineStockSpan.next(4);
        assertEquals(-1, result);

        when(onlineStockSpan.next(anyInt())).thenReturn(-1);
        result = onlineStockSpan.next(5);
        assertEquals(-1, result);

        when(onlineStockSpan.next(anyInt())).thenReturn(-1);
        result = onlineStockSpan.next(2);
        assertEquals(-1, result);

        when(onlineStockSpan.next(anyInt())).thenReturn(-1);
        result = onlineStockSpan.next(0);
        assertEquals(-1, result);

        when(onlineStockSpan.next(anyInt())).thenReturn(-1);
        result = onlineStockSpan.next(3);
        assertEquals(-1, result);

        when(onlineStockSpan.next(anyInt())).thenReturn(-1);
        result = onlineStockSpan.next(3);
        assertEquals(-1, result);

        when(onlineStockSpan.next(anyInt())).thenReturn(-1);
        result = onlineStockSpan.next(2);
        assertEquals(-1, result);
    }

    @Test
    public void test_calculateSpans() {
        int[] prices = new int[]{3, 2, 6, -0.8, 1.4, 5};
        when(onlineStockSpan.calculateSpans(prices)).thenReturn(new int[]{2, 1, 1, 2, 3});

        for (int i : onlineStockSpan.calculateSpans(prices)) {
            assertEquals(i, 0); // index 0 has price of -1
        }
    }

    @Test
    public void test_calculateSpans_priceNotFound() {
        int[] prices = new int[]{1, 3, 5};
        when(onlineStockSpan.calculateSpans(prices)).thenReturn(new int[]{});

        for (int i : onlineStockSpan.calculateSpans(prices)) {
            assertEquals(0, i);
        }
    }

    @Test
    public void test_calculateSpans_priceNotFound_2() {
        int[] prices = new int[]{1, 3, 5};
        when(onlineStockSpan.calculateSpans(prices)).thenReturn(new int[]{});

        for (int i : onlineStockSpan.calculateSpans(prices)) {
            assertEquals(-1, i);
        }
    }

    @Test
    public void test_calculateSpans_priceNotFound_0() {
        int[] prices = new int[]{1, 3, 5};
        when(onlineStockSpan.calculateSpans(prices)).thenReturn(new int[]{});

        for (int i : onlineStockSpan.calculateSpans(prices)) {
            assertEquals(-1, i);
        }
    }

    @Test
    public void test_calculateSpans_emptyPrices() {
        int[] prices = new int[]{0};
        when(onlineStockSpan.calculateSpans(prices)).thenReturn(new int[]{});

        for (int i : onlineStockSpan.calculateSpans(prices)) {
            assertEquals(0, i);
        }
    }

}
